"""Legacy-compatible EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from typing import Any

__all__ = ["format_account"]


def _text(value: Any) -> str:
    """Convert a legacy value to text; missing/null-like values are blank."""
    if value is None:
        return ""
    return str(value)


def _fixed(value: Any, width: int) -> str:
    """Left-align and space-pad or truncate to the specified width."""
    return _text(value)[:width].ljust(width)


def _zpad_cents(value: Any, width: int) -> str:
    """Convert an amount to half-up rounded integer cents and zero-pad it."""
    text = _text(value)
    if text == "":
        text = "0"

    try:
        amount = Decimal(text)
    except (InvalidOperation, ValueError) as exc:
        raise ValueError(f"ANN_REV is not a valid decimal value: {text!r}") from exc

    if not amount.is_finite():
        raise ValueError(f"ANN_REV must be finite: {text!r}")

    precision = max(50, len(amount.as_tuple().digits) + abs(amount.as_tuple().exponent) + 10)
    with localcontext() as context:
        context.prec = precision
        cents = (amount * Decimal(100)).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )

    rendered = str(cents)
    if len(rendered) > width:
        raise ValueError(f"ANN_REV cents do not fit in {width} characters")

    return rendered.zfill(width)


def format_account(row: dict) -> str:
    """Build one 77-character legacy EXPORT_ACCT record without a newline."""
    account_id = _fixed(row.get("ACCT_ID", ""), 10)
    account_name = _fixed(row.get("ACCT_NM", ""), 40)
    region_code = _fixed(row.get("REGION_CD", ""), 3)
    annual_revenue = _zpad_cents(row.get("ANN_REV", ""), 15)

    credit_hold = _text(row.get("CRED_HOLD", ""))
    if credit_hold == "":
        credit_hold = "N"
    if len(credit_hold) != 1:
        raise ValueError("CRED_HOLD must be exactly one character when nonblank")

    create_date = _text(row.get("CREATE_DT", ""))
    if create_date == "":
        create_date = "00000000"
    if len(create_date) != 8:
        raise ValueError("CREATE_DT must be exactly eight characters when nonblank")

    record = (
        account_id
        + account_name
        + region_code
        + annual_revenue
        + credit_hold
        + create_date
    )

    if len(record) != 77:
        raise AssertionError("EXPORT_ACCT record must be exactly 77 characters")

    return record
